entries[15783] = { ["name"] = "Blizzard", ["text"] = "8 Mana 30 Meter Reichweite\nWirken in 2 sek.\nRuft einen Blizzard herbei, der 10 Sek. lang anhält und Feinden im ausgewählten Gebiet alle 2 Sek. 6 Punkt(e) Frostschaden zufügt." }
entries[15784] = { ["name"] = "Frostrüstung", ["text"] = "10 Mana 20 Meter Reichweite\nSofort\nUmgibt einen Verbündeten mit einer Frostschicht, die 1 Min. lang bestehen bleibt. Das dicke Eis erhöht die Rüstung um 12, verlangsamt das Bewegungstempo von Nahkampfangreifern um 25% und erhöht die Zeit zwischen ihren Angriffen um 30%." }
entries[15785] = { ["name"] = "Manabrand", ["text"] = "95 Mana 30 Meter Reichweite\nWirken in 2 sek.\nTrifft einen Feind mit einem Antimanablitz. Für jeden vom Blitz verbrauchten Manapunkt erleidet das Ziel 0.5 Punkt(e) Schaden." }
entries[15786] = { ["name"] = "Totem der Erdbindung", ["text"] = "40 Mana\nSofort\nTools: Erdtotem\nBeschwört ein Totem der Erdbindung, das 45 Sek. lang bestehen bleibt und in regelmäßigen Abständen das Bewegungstempo von in der Nähe befindlichen Feinden auf 50% des normalen Tempos verringert." }
entries[15787] = { ["name"] = "Mondleuchtfeuer-Totem", ["text"] = "200 Mana\nSofort\nTools: Feuertotem\nBeschwört ein Mondleuchtfeuer-Totem zu Füßen des Zaubernden. Das Totem bleibt 5 Sek. lang bestehen und fügt in der Nähe befindlichen Feinden alle 4 Sek. Arkanschaden zu." }
