entries[15799] = { ["name"] = "Kettenheilung", ["text"] = "150 Mana 40 Meter Reichweite\nWirken in 2.5 sek.\nErfüllt einen verwundeten Verbündeten mit Heilenergie, die sich auf einen anderen in der Nähe befindlichen Verbündeten ausbreitet. Der Zauber wirkt sich auf bis zu 3 Ziele aus, aber die Heilenergie wird bei jedem folgenden Ziel um 50% reduziert." }
